// 応答が返らなかった PAYMENT_FAILED でも、課金の記録があれば PAID に直す
const recentFailed = await orders.findByStatusUpdatedBetween(
  'PAYMENT_FAILED', new Date(now.getTime() - DAY_MS), now);
for (const order of recentFailed) {
  const charge = await payments.findCharge(paymentKeyFor(order));
  if (!charge) continue; // 記録がなければ書かない（やり直しの途中かもしれない）
  order.status = 'PAID';
  order.chargeId = charge.chargeId;
  await orders.save(order);
}
